static void concatInternal_checkArrayIndex(int64_t length,int64_t index,char const* pos){
  if(index>=0 && index<length)
    return;
  fprintf(stderr,"array index out of bounds: %"PRIi64" size: %"PRIi64" at %s\n",index,length,pos);
  exit(1);
}
static void concatInternal_checkEnumIndex(int64_t current,int64_t expected,char const* pos){
  if(current==expected)
    return;
  fprintf(stderr,"enum index (%"PRIi64") does not match current value (%"PRIi64") at %s\n",expected,current,pos);
  exit(2);
}
